physical SQLite table: "Categories"
CREATE TABLE "Categories" (
  "CategoryID" TEXT -- PRIMARY KEY
  "CategoryDescription" TEXT
  "DepartmentID" INTEGER
);

physical SQLite table: "Class_Rooms"
CREATE TABLE "Class_Rooms" (
  "ClassRoomID" INTEGER -- PRIMARY KEY
  "BuildingCode" TEXT -- REFERENCES "Buildings"("BuildingCode")
  "PhoneAvailable" BOOLEAN
);

physical SQLite table: "Departments"
CREATE TABLE "Departments" (
  "DepartmentID" INTEGER -- PRIMARY KEY
  "DeptName" TEXT
  "DeptChair" INTEGER -- REFERENCES "Staff"("StaffID")
);

physical SQLite table: "Faculty_Categories"
CREATE TABLE "Faculty_Categories" (
  "StaffID" INTEGER -- PRIMARY KEY; REFERENCES "Faculty"("StaffID")
  "CategoryID" TEXT -- PRIMARY KEY; REFERENCES "Categories"("CategoryID")
);

physical SQLite table: "Faculty_Classes"
CREATE TABLE "Faculty_Classes" (
  "ClassID" INTEGER -- PRIMARY KEY; REFERENCES "Classes"("ClassID")
  "StaffID" INTEGER -- PRIMARY KEY; REFERENCES "Staff"("StaffID")
);

physical SQLite table: "Faculty_Subjects"
CREATE TABLE "Faculty_Subjects" (
  "StaffID" INTEGER -- PRIMARY KEY; REFERENCES "Faculty"("StaffID")
  "SubjectID" INTEGER -- PRIMARY KEY; REFERENCES "Subjects"("SubjectID")
  "ProficiencyRating" REAL
);

physical SQLite table: "Majors"
CREATE TABLE "Majors" (
  "MajorID" INTEGER -- PRIMARY KEY
  "Major" TEXT
);

physical SQLite table: "Student_Class_Status"
CREATE TABLE "Student_Class_Status" (
  "ClassStatus" INTEGER -- PRIMARY KEY
  "ClassStatusDescription" TEXT
);

